<script>
(()=>{const products=<?= json_encode($products, JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?>,key=<?= json_encode('tmp-store-cart-'.$store['uid']) ?>,viewKey=<?= json_encode('tmp-store-view-'.$store['uid']) ?>;let cart={};try{cart=JSON.parse(localStorage.getItem(key)||'{}')||{}}catch(e){}const update=()=>document.querySelector('[data-cart-count]').textContent=Object.values(cart).reduce((s,i)=>s+Number(i.quantity||0),0);document.querySelectorAll('[data-add]').forEach(button=>button.onclick=()=>{const product=products[Number(button.dataset.add)];if(!product)return;const item=cart[product.uid]||{product,quantity:0};item.product=product;item.quantity=Math.min(99,Number(item.quantity)+1);cart[product.uid]=item;localStorage.setItem(key,JSON.stringify(cart));update();button.textContent='✓';setTimeout(()=>button.textContent='+',800)});document.querySelector('[data-filter-toggle]')?.addEventListener('click',event=>{const panel=document.querySelector('[data-filters]'),open=panel.classList.toggle('open');event.currentTarget.textContent=open?'✕ Ocultar filtros':'☰ Mostrar filtros'});const grid=document.querySelector('.page .grid');function setView(view){view=view==='list'?'list':'grid';grid?.classList.toggle('list',view==='list');document.querySelectorAll('[data-view]').forEach(button=>button.classList.toggle('active',button.dataset.view===view));localStorage.setItem(viewKey,view)}document.querySelectorAll('[data-view]').forEach(button=>button.onclick=()=>setView(button.dataset.view));setView(localStorage.getItem(viewKey)||'grid');update()})();
</script>
<?php if($store['show_stock']): ?><script>document.querySelectorAll('.product .badge').forEach((badge,index)=>{const product=<?= json_encode($products, JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_HEX_TAG) ?>[index];if(product?.available&&product.stock!==null)badge.textContent=Number(product.stock).toLocaleString('es-DO',{maximumFractionDigits:0})+' disponibles'});</script><?php endif; ?>
